package com.auditlog.api.controller;
import com.auditlog.api.dto.ClientAccountAccessReport; import com.auditlog.api.response.ApiResponse; import com.auditlog.application.service.ClientAccountAccessReportService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.constraints.NotBlank; import org.slf4j.MDC; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestController @RequestMapping("/api/v1/compliance") @Tag(name="Compliance Reporting",description="Client-account access audit reporting") public class ComplianceReportingController {private final ClientAccountAccessReportService service; public ComplianceReportingController(ClientAccountAccessReportService s){service=s;} @GetMapping("/client-account-access") @Operation(summary="Report access to a client account",description="Read-only account access report with chain integrity metadata and no plaintext payload.") public ApiResponse<ClientAccountAccessReport> report(@RequestParam @NotBlank String accountId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant to){return ApiResponse.success(service.report(accountId,from,to),MDC.get("traceId"));}}
